@IsTest private class OwnedSearchWindowProbe {
    @IsTest static void sw01() { observe('SW01', false, true); }
    @IsTest static void sw02() { observe('SW02', true, true); }
    @IsTest static void sw03() { observe('SW03', false, false); }
    private static void observe(String row, Boolean oldBody, Boolean fixedIds) {
        String token = String.valueOf(Datetime.now().getTime());
        Account headline = new Account(Name='ownedneedle short '+token);
        Account body = new Account(Name='Owned body '+token, Description='ownedneedle body text');
        insert new List<Account>{headline,body};
        if (oldBody) Test.setCreatedDate(body.Id, Datetime.now().addDays(-4));
        Datetime lower = Datetime.now().addDays(-1);
        Datetime upper = Datetime.now();
        String term = 'ownedneedle';
        String pattern = '%'+term+'%';
        if (fixedIds) Test.setFixedSearchResults(new List<Id>{body.Id});
        Test.startTest();
        Set<Id> headlineIds = new Map<Id,Account>([SELECT Id FROM Account WHERE Name LIKE :pattern AND CreatedDate >= :lower AND CreatedDate <= :upper]).keySet();
        List<List<SObject>> unfiltered = Search.query('FIND :term IN ALL FIELDS RETURNING Account(Id)', AccessLevel.SYSTEM_MODE);
        Set<Id> bodyIds = new BodyFinder().find(term,lower,upper);
        Set<Id> allIds = new Set<Id>(); allIds.addAll(headlineIds); allIds.addAll(bodyIds);
        Map<String,Object> observed = new Map<String,Object>{
            'shortCount'=>headlineIds.size(), 'bodyCount'=>bodyIds.size(), 'unionCount'=>allIds.size(),
            'unfilteredFixedCount'=>unfiltered[0].size(), 'hasBody'=>bodyIds.contains(body.Id)
        };
        Test.stopTest();
        System.assert(false,'SEARCH_WINDOW|'+row+'|'+JSON.serialize(observed));
    }
    private without sharing class BodyFinder {
        Set<Id> find(String term, Datetime lower, Datetime upper) {
            String statement = 'FIND :term IN ALL FIELDS RETURNING Account(Id WHERE CreatedDate >= '
                +lower.formatGmt('yyyy-MM-dd\'T\'HH:mm:ss\'Z\'')+' AND CreatedDate <= '
                +upper.formatGmt('yyyy-MM-dd\'T\'HH:mm:ss\'Z\'')+' ORDER BY CreatedDate DESC)';
            Set<Id> ids = new Set<Id>();
            for(SObject item : Search.query(statement,AccessLevel.SYSTEM_MODE)[0]) ids.add(item.Id);
            return ids;
        }
    }
}
